// Rounding helpers for integer-cent money math.

/**
 * Round a cent amount half-up (2.5 -> 3, -2.5 -> -2), i.e. Math.round semantics.
 * Used by: statement.mjs (late fees - half-up is
 * written into the customer agreement, do not change for statements).
 */
export function roundCents(x) {
  return Math.round(x);
}

/**
 * Round half to even (banker's rounding), symmetric for negatives.
 * 2.5 -> 2, 3.5 -> 4, -2.5 -> -2, -3.5 -> -4
 */
export function roundHalfEven(x) {
  if (x === 0) return 0;
  const sign = x < 0 ? -1 : 1;
  const abs = Math.abs(x);
  const floor = Math.floor(abs);
  const frac = abs - floor;
  const EPS = 1e-12;
  if (Math.abs(frac - 0.5) < EPS) {
    return sign * (floor % 2 === 0 ? floor : floor + 1);
  }
  return sign * Math.round(abs);
}

/**
 * Banker's rounding for integer division numerator/denominator.
 * Avoids floating point errors by using integer arithmetic.
 */
export function bankersRoundDiv(numerator, denominator) {
  if (!Number.isInteger(denominator) || denominator <= 0) throw new RangeError('denominator must be a positive integer');
  if (!Number.isInteger(numerator)) throw new TypeError('numerator must be an integer');
  if (numerator === 0) return 0;
  const sign = numerator < 0 ? -1 : 1;
  const absN = Math.abs(numerator);
  const q = Math.trunc(absN / denominator);
  const r = absN % denominator;
  const twiceR = r * 2;
  if (twiceR < denominator) return sign * q;
  if (twiceR > denominator) return sign * (q + 1);
  // exactly half -> to even
  return sign * (q % 2 === 0 ? q : q + 1);
}

